/**
 * Hex values for the Tailwind palette names stored in the database
 * (categories.gradient_from / gradient_to). Classes built at runtime like
 * `from-${name}` are never generated by Tailwind, so we use inline styles.
 */
const PALETTE: Record<string, string> = {
  "purple-500": "#a855f7", "purple-600": "#9333ea",
  "pink-500": "#ec4899",
  "blue-500": "#3b82f6",
  "cyan-400": "#22d3ee", "cyan-500": "#06b6d4",
  "indigo-500": "#6366f1",
  "rose-500": "#f43f5e",
  "orange-500": "#f97316",
  "emerald-500": "#10b981",
  "green-500": "#22c55e",
  "amber-500": "#f59e0b",
  "yellow-500": "#eab308",
  "red-500": "#ef4444",
  "teal-500": "#14b8a6",
  "slate-400": "#94a3b8", "slate-600": "#475569",
  "neutral-400": "#a3a3a3", "neutral-600": "#525252",
  "stone-400": "#a8a29e", "stone-600": "#57534e",
  "gray-400": "#9ca3af", "gray-600": "#4b5563",
};

export function paletteColor(name: string | null | undefined, fallback = "#6366f1"): string {
  return (name && PALETTE[name]) || fallback;
}

export function gradientStyle(from?: string | null, to?: string | null) {
  return {
    backgroundImage: `linear-gradient(to bottom right, ${paletteColor(from, "#6366f1")}, ${paletteColor(to, "#a855f7")})`,
  };
}
